<?php require_once __DIR__.'/../config/config.php';require_admin();$error='';if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$event=trim($_POST['event_name']??'');$guest=trim($_POST['guest_link']??'');$full=trim($_POST['full_access_link']??'');$client=(int)($_POST['client_id']??0);if($event===''||!filter_var($guest,FILTER_VALIDATE_URL)||!str_starts_with($guest,'https://'))$error='Enter an event name and a valid HTTPS guest gallery URL.';else{$q=$pdo->prepare('INSERT INTO client_galleries(client_id,event_name,event_date,guest_link,full_access_link,description,status) VALUES(?,?,?,?,?,?,?)');$q->execute([$client?:null,$event,$_POST['event_date']?:null,$guest,$full?:null,trim($_POST['description']??''),'active']);flash('notice','Gallery link saved.');header('Location: galleries.php');exit;}}
$pageTitle='Foto Owl galleries';$active='galleries';$description='Attach a Foto Owl event gallery to the right client account.';$rows=[];try{$sql=$pdo->query('SELECT g.*,c.name AS client_name FROM client_galleries g LEFT JOIN clients c ON c.id=g.client_id ORDER BY g.created_at DESC LIMIT 200')->fetchAll();foreach($sql as $g)$rows[]=['<b>'.e($g['event_name']).'</b><small class="cell-sub">'.e($g['event_date']?:'Date not set').'</small>',e($g['client_name']?:'Unassigned'),'<a class="text-link" href="'.e($g['guest_link']).'" target="_blank" rel="noopener">Open guest gallery ↗</a>',e(ucfirst($g['status']))];}catch(Throwable $e){}$columns=['EVENT','CLIENT','GUEST PREVIEW','STATUS'];require __DIR__.'/_layout.php';?>
<section class="welcome-row"><div><p class="eyebrow">CLIENT DELIVERY</p><h1>Every memory, <em>in one place.</em></h1><p class="muted">Save the Foto Owl guest link here. Clients see their assigned gallery after signing in.</p></div></section><?php if($error):?><div class="alert"><?=e($error)?></div><?php endif;?><section class="panel form-panel"><div class="panel-head"><div><p class="eyebrow">NEW GALLERY</p><h2>Connect Foto Owl event</h2></div><span class="period-chip">HTTPS LINK REQUIRED</span></div><form method="post" class="form-grid"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><label>Event name<input name="event_name" required placeholder="e.g. Sobara wedding"></label><label>Client ID (optional)<input type="number" name="client_id" min="1" placeholder="Client record ID"></label><label>Event date<input type="date" name="event_date"></label><label>Guest access link<input type="url" name="guest_link" required placeholder="https://site.fotoowl.ai/..."></label><label class="span-2">Full access link (admin only)<input type="url" name="full_access_link" placeholder="Paste full-access link; keep it private"></label><label class="span-2">Description<input name="description" placeholder="Wedding, event or delivery note"></label><div class="span-2"><button class="btn btn-primary">Save gallery link ↗</button></div></form><p class="tiny muted">Never expose a full-access link to clients or public pages. Guest links may also be shareable, so confirm Foto Owl access controls before assigning.</p></section><section class="panel"><div class="panel-head"><div><p class="eyebrow">CONNECTED EVENTS</p><h2>Saved galleries</h2></div></div><div class="table-wrap"><table><thead><tr><?php foreach($columns as $c):?><th><?=e($c)?></th><?php endforeach;?></tr></thead><tbody><?php foreach($rows as $r):?><tr><?php foreach($r as $v):?><td><?=$v?></td><?php endforeach;?></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="4" class="empty">No galleries connected yet.</td></tr><?php endif;?></tbody></table></div></section><?php require __DIR__.'/_footer.php';?>
